725|	   | ((attr & SHF_MERGE) ? SEC_MERGE : 0)
726|	   | ((attr & SHF_STRINGS) ? SEC_STRINGS : 0)
727|	   | ((attr & SHF_EXCLUDE) ? SEC_EXCLUDE: 0)
728|	   | ((attr & SHF_TLS) ? SEC_THREAD_LOCAL : 0));
