816|		  | SEC_EXCLUDE | SEC_SORT_ENTRIES | SEC_MERGE | SEC_STRINGS
817|		  | SEC_LINK_ONCE | SEC_LINK_DUPLICATES_DISCARD
818|		  | SEC_THREAD_LOCAL)))
