2886|	     signature symbols, so make them weak hidden instead.  */
2887|	  symbol_get_bfdsym (sy)->flags |= BSF_WEAK;
2888|	  S_SET_OTHER (sy, STV_HIDDEN);
2889|#else
2890|	  symbol_get_obj (sy)->local = 1;
2891|#endif
2892|	  symbol_table_insert (sy);
2893|	}
