487|static void
488|define_sym_at_dot (symbolS *symbolP)
489|{
490|  symbolP->frag = frag_now;
491|  S_SET_VALUE (symbolP, (valueT) frag_now_fix ());
492|  S_SET_SEGMENT (symbolP, now_seg);
