965|symbolS *
966|symbol_find_noref (const char *name, int noref)
967|{
968|  symbolS * result;
969|  char * copy = NULL;
970|
971|#ifdef tc_canonicalize_symbol_name
972|  {
973|    copy = xstrdup (name);
974|    name = tc_canonicalize_symbol_name (copy);
975|  }
976|#endif
977|
978|  if (! symbols_case_sensitive)
979|    {
980|      const char *orig;
981|      char *copy2 = NULL;
982|      unsigned char c;
983|
984|      orig = name;
985|      if (copy != NULL)
986|	copy2 = copy;
987|      name = copy = XNEWVEC (char, strlen (name) + 1);
988|
989|      while ((c = *orig++) != '\0')
990|	*copy++ = TOUPPER (c);
991|      *copy = '\0';
992|
993|      free (copy2);
994|      copy = (char *) name;
995|    }
996|
997|  result = symbol_find_exact_noref (name, noref);
998|  free (copy);
999|  return result;
