256|void *
257|notes_calloc (size_t n, size_t size)
258|{
259|  size_t amt;
260|  void *ret;
261|  if (gas_mul_overflow (n, size, &amt))
262|    {
263|      obstack_alloc_failed_handler ();
264|      abort ();
265|    }
266|  ret = notes_alloc (amt);
