1186|	  && S_IS_DEFINED (symp->x->value.X_op_symbol)
1187|	  && S_GET_SEGMENT (symp->x->value.X_op_symbol) != expr_section)
1188|	{
1189|	case O_symbol:
1190|	case O_symbol_rva:
1191|	case O_uminus:
