1195|	       || S_IS_LOCAL (symp->x->value.X_add_symbol))
1196|	      && S_IS_DEFINED (symp->x->value.X_add_symbol)
1197|	      && S_GET_SEGMENT (symp->x->value.X_add_symbol) != expr_section)
1198|	    return 0;
1199|	}
1200|      break;
